=== tests/log-summary.test.mjs ===
import assert from "node:assert/strict";
import { test } from "node:test";
import { summarize } from "../scripts/log-summary.mjs";

test("counts events per level and reports the time range", () => {
  const text = [
    '{"time":"2026-01-02T00:00:00Z","level":"info"}',
    '{"time":"2026-01-01T00:00:00Z","level":"error"}',
    '{"time":"2026-01-03T00:00:00Z","level":"info"}',
  ].join("\n");
  assert.deepEqual(summarize(text), {
    levels: { info: 2, error: 1 },
    first: "2026-01-01T00:00:00Z",
    last: "2026-01-03T00:00:00Z",
  });
});

test("ignores blank lines", () => {
  assert.deepEqual(summarize('\n{"time":"2026-01-01T00:00:00Z","level":"warn"}\n'), {
    levels: { warn: 1 },
    first: "2026-01-01T00:00:00Z",
    last: "2026-01-01T00:00:00Z",
  });
});
