```js
#!/usr/bin/env node
// Summarize a JSONL event log: counts per level, plus the time range.

import { readFileSync } from "node:fs";

function parseArgs(argv) {
  let since;
  const positional = [];
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === "--since") {
      since = argv[++i];
    } else {
      positional.push(argv[i]);
    }
  }
  return { file: positional[0] ?? "fixtures/events.jsonl", since };
}

export function summarize(text, { since } = {}) {
  const sinceMs = since === undefined ? null : Date.parse(since);
  const levels = {};
  const times = [];
  for (const line of text.split(/\r?\n/)) {
    if (!line.trim()) continue;
    const event = JSON.parse(line);
    if (sinceMs !== null) {
      const eventMs = typeof event.time === "string" ? Date.parse(event.time) : NaN;
      if (Number.isNaN(eventMs) || eventMs < sinceMs) continue;
    }
    levels[event.level] = (levels[event.level] ?? 0) + 1;
    if (event.time) times.push(event.time);
  }
  times.sort();
  return { levels, first: times[0] ?? null, last: times[times.length - 1] ?? null };
}

if (import.meta.url === new URL(`file://${process.argv[1]}`).href) {
  const { file, since } = parseArgs(process.argv.slice(2));
  const text = readFileSync(file, "utf8");
  const summary = since === undefined ? summarize(text) : summarize(text, { since });
  console.log(JSON.stringify(summary, null, 2));
}
```

